  const statusFor = (n) => { const p = proposalState.active; if (!p) return 'empty'; return (n === 1 ? p.state : n === 2 ? p.step2_state : n === 3 ? p.step3_state : n === 4 ? p.step4_state : 'draft') || 'draft'; };
  const maxReachableStep = () => { for (let n = 1; n <= 4; n += 1) if (statusFor(n) !== 'locked') return n; return 5; };
  const syncStepNavigation = () => { const max = maxReachableStep(); steps.querySelectorAll('[data-guided-action="step"]').forEach(el => { const n = Number(el.dataset.step); if (n <= max) el.removeAttribute('aria-disabled'); else el.setAttribute('aria-disabled','true'); }); };
  const renderList = () => { list.innerHTML = proposalState.setups.length ? proposalState.setups.map(p => `<div class="report-item ${p.id === proposalState.active?.id ? 'active' : ''}" data-guided-action="select" data-id="${guidedEsc(p.id)}" style="cursor:pointer;padding:10px;border-bottom:1px solid var(--border-light);"><div class="report-item-title" style="font-weight:600;font-size:13px">${guidedEsc(p.project_title || 'Untitled proposal')}</div><div class="report-item-meta" style="font-size:11px;color:var(--text-muted)">${guidedEsc(p.country || 'Country pending')} · ${guidedEsc(donorFor(p.donor).label || p.donor || 'Donor pending')}</div></div>`).join('') : '<div class="empty-state">No guided proposals yet</div>'; };
  const renderSteps = () => { if (!proposalState.active) { steps.innerHTML = ''; return; } const current = proposalState.step; steps.innerHTML = PROPOSAL_STEPS.map((s, i) => { const locked = statusFor(i + 1) === 'locked'; const active = i + 1 === current; return `<div class="wizard-step ${active ? 'active' : ''} ${locked ? 'complete' : ''}" data-guided-action="step" data-step="${i + 1}" ${i + 1 > current ? 'aria-disabled="true"' : ''}><span class="wizard-step-num">${locked ? '✓' : s.num}</span><span class="wizard-step-label">${s.label}</span><span class="wizard-step-icon">${locked ? '✓' : '○'}</span></div>`; }).join(''); const fill = document.getElementById('wizard-progress-fill'); if (fill) fill.style.width = `${((proposalState.step - 1) / 4) * 100}%`; };
  const field = (label, key, value, type = 'text', extra = '') => `<label class="form-group" style="display:block;margin-bottom:14px"><span style="display:block;font-size:11px;font-weight:700;color:var(--text-muted);margin-bottom:5px">${label}</span>${type === 'textarea' ? `<textarea class="fi" data-guided-field="${key}" ${extra} style="width:100%;resize:vertical">${guidedEsc(value)}</textarea>` : `<input class="fi" data-guided-field="${key}" type="${type}" value="${guidedEsc(value)}" ${extra} style="width:100%">`}</label>`;
  const donorCard = proposal => { const donor = donorFor(proposal.donor); return `<div class="proposal-donor-card"><div><span class="proposal-kicker">Active donor framework</span><h4>${guidedEsc(donor.full_name || 'Choose a donor')}</h4><p>${guidedEsc(donor.framework_standard || 'Select a donor to load its rules.')}</p></div><div class="proposal-rule-stats"><span><b>${guidedEsc((donor.currency_options || []).join(' / ') || '—')}</b>Currency</span><span><b>${donor.max_duration_months || '—'} mo</b>Max duration</span><span><b>${donor.overhead_ceiling_percent ?? '—'}%</b>Overhead ceiling</span></div>${donor.special_requirements?.length ? `<details><summary>Key donor requirements</summary><ul>${donor.special_requirements.slice(0,6).map(item => `<li>${guidedEsc(item)}</li>`).join('')}</ul></details>` : ''}</div>`; };
  if (!document.getElementById('proposal-matrix-style')) { const style = document.createElement('style'); style.id = 'proposal-matrix-style'; style.textContent = '.proposal-matrix-wrap{margin:8px 0 18px;overflow:auto;border:1px solid var(--border-light);border-radius:10px}.proposal-editor-caption{display:flex;justify-content:space-between;gap:12px;padding:12px 14px;background:var(--bg-subtle);font-size:12px}.proposal-editor-caption span{color:var(--text-muted);font-size:11px}.proposal-matrix{width:100%;border-collapse:collapse;min-width:760px}.proposal-matrix th,.proposal-matrix td{padding:9px 8px;border-top:1px solid var(--border-light);font-size:11px;text-align:right}.proposal-matrix th:first-child{text-align:left}.proposal-matrix thead th{background:var(--bg-subtle);font-weight:700;color:var(--text-muted);white-space:nowrap}.proposal-matrix input{width:72px;padding:6px;border:1px solid var(--border-light);border-radius:6px;text-align:right;background:var(--bg-card);color:var(--text-primary)}.proposal-matrix .matrix-total{font-weight:800;color:var(--primary)}'; document.head.appendChild(style); }
