  const refresh = async () => { proposalState.setups = await guidedRequest('/api/proposals/setups'); if (!proposalState.active && proposalState.setups[0]) proposalState.active = await guidedRequest(`/api/proposals/setups/${proposalState.setups[0].id}`); render(); };
  const openPreflight = () => { if (document.getElementById('proposal-preflight-modal')) return; panel.insertAdjacentHTML('beforeend', `<div id="proposal-preflight-modal" class="proposal-preflight-backdrop"><div class="proposal-preflight-card" role="dialog" aria-modal="true" aria-labelledby="proposal-preflight-title"><div class="proposal-preflight-head"><div><span class="proposal-kicker">Proposal intake</span><h3 id="proposal-preflight-title">Start a new proposal</h3><p>Upload the donor call and add only the basics. The detailed Project Setup comes next.</p></div><button class="btn-icon-ghost" data-proposal-preflight="cancel" aria-label="Close">×</button></div><div class="up-grid"><label class="form-group"><span>Project title</span><input class="fi" data-preflight-field="project_title" minlength="10" maxlength="150" placeholder="e.g. Preventing CEFM in Eastern Türkiye" required></label><label class="form-group"><span>Target country</span><input class="fi" data-preflight-field="country" list="proposal-preflight-countries" placeholder="Select or type a country" required><datalist id="proposal-preflight-countries">${(proposalState.countries || []).slice(0,200).map(c => `<option value="${guidedEsc(typeof c === 'string' ? c : c.name || c.country || '')}">`).join('')}</datalist></label></div><label class="form-group"><span>Initial executive intent <em style="font-style:normal;font-weight:400">optional · 100–500 characters</em></span><textarea class="fi" data-preflight-field="executive_intent" rows="4" minlength="100" maxlength="500" placeholder="You can leave this empty and shape it in Project Setup."></textarea></label><label class="proposal-preflight-upload"><strong>Grant call document</strong><span>Required · DOCX, TXT or Markdown</span><input type="file" data-preflight-field="reference" accept=".docx,.txt,.md" required></label><div class="proposal-preflight-actions"><button class="btn btn-secondary" data-proposal-preflight="cancel">Cancel</button><button class="btn btn-primary" data-proposal-preflight="submit">Open Project Setup</button></div></div></div>`); };
  const create = async () => openPreflight();
  panel.addEventListener('click', async e => { const submit = e.target.closest('[data-proposal-preflight="submit"]'); if (!submit) return; e.preventDefault(); e.stopImmediatePropagation(); const modal = document.getElementById('proposal-preflight-modal'); const value = key => modal?.querySelector(`[data-preflight-field="${key}"]`)?.value?.trim() || ''; const file = modal?.querySelector('[data-preflight-field="reference"]')?.files?.[0]; if (!modal || !file || !value('project_title') || !value('country')) { setNotice('Project title, target country and a grant call document are required.', true); return; } try { const data = {project_title:value('project_title'),country:value('country'),region:'',donor:'generic',budget_amount:null,budget_currency:'USD',executive_intent:value('executive_intent'),sectors:[]}; proposalState.active = await guidedRequest('/api/proposals/setups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); const fd = new FormData(); fd.append('file',file); await guidedRequest(`/api/proposals/setups/${proposalState.active.id}/upload-reference`,{method:'POST',body:fd}); proposalState.step = 1; modal.remove(); await refresh(); proposalState.active = await guidedRequest(`/api/proposals/setups/${proposalState.active.id}`); render(); setNotice('Project Setup opened. Complete donor, budget and the remaining Step 1 rules.'); } catch (err) { setNotice(err.message, true); } }, true);
